package main

import (
	"context"
	"crypto/tls"
	"fmt"
	"io"
	"log"
	"net"
	"net/http"
	"os"
	"strings"
	"sync"
	"time"
)

// ServiceRegistry holds discovered backend endpoints from K8s service discovery
type ServiceRegistry struct {
	mu       sync.RWMutex
	backends map[string]*BackendPool
}

// BackendPool represents a pool of connections to a backend service
type BackendPool struct {
	Endpoints []string
	Healthy   []bool
	TLSConfig *tls.Config
	connCache sync.Map
}

// ConnectionState tracks per-connection proxy state
type ConnectionState struct {
	Upstream   net.Conn
	Downstream net.Conn
	Pool       *BackendPool
	StartTime  time.Time
	BytesIn    int64
	BytesOut   int64
}

var registry = &ServiceRegistry{
	backends: make(map[string]*BackendPool),
}

func (sr *ServiceRegistry) Lookup(host string) *BackendPool {
	sr.mu.RLock()
	defer sr.mu.RUnlock()
	pool, exists := sr.backends[host]
	if !exists {
		return nil
	}
	return pool
}

func (sr *ServiceRegistry) Register(host string, pool *BackendPool) {
	sr.mu.Lock()
	defer sr.mu.Unlock()
	sr.backends[host] = pool
}

// resolveBackend selects a healthy endpoint from the pool
// Returns the endpoint address and the TLS config for upstream connection
func resolveBackend(pool *BackendPool) (string, *tls.Config) {
	if pool == nil {
		return "", nil
	}
	for i, healthy := range pool.Healthy {
		if healthy {
			return pool.Endpoints[i], pool.TLSConfig
		}
	}
	return "", pool.TLSConfig
}

// initUpstreamConn establishes connection to the selected backend
func initUpstreamConn(ctx context.Context, addr string, tlsCfg *tls.Config) (net.Conn, error) {
	if addr == "" {
		return nil, fmt.Errorf("no backend address available")
	}

	dialer := &net.Dialer{Timeout: 5 * time.Second}

	if tlsCfg != nil {
		return tls.DialWithDialer(dialer, "tcp", addr, tlsCfg)
	}
	return dialer.DialContext(ctx, "tcp", addr)
}

// handleConnection processes a proxied connection through the mesh
func handleConnection(downstream net.Conn, targetHost string) {
	defer downstream.Close()

	pool := registry.Lookup(targetHost)

	// Attempt to get connection parameters from pool
	addr, tlsCfg := resolveBackend(pool)

	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	upstream, err := initUpstreamConn(ctx, addr, tlsCfg)
	if err != nil {
		log.Printf("upstream connection failed for %s: %v", targetHost, err)
		return
	}
	defer upstream.Close()

	state := &ConnectionState{
		Upstream:   upstream,
		Downstream: downstream,
		Pool:       pool,
		StartTime:  time.Now(),
	}

	// Bidirectional copy with metrics tracking
	proxyTraffic(state)
}

// proxyTraffic performs bidirectional data transfer and updates metrics
func proxyTraffic(state *ConnectionState) {
	done := make(chan struct{}, 2)

	go func() {
		n, _ := io.Copy(state.Upstream, state.Downstream)
		state.BytesIn = n
		done <- struct{}{}
	}()

	go func() {
		n, _ := io.Copy(state.Downstream, state.Upstream)
		state.BytesOut = n
		done <- struct{}{}
	}()

	<-done

	// Record metrics using pool reference - pool may be nil if service was
	// deregistered during connection lifetime (hot-reload scenario)
	recordMetrics(state)
}

// recordMetrics updates the connection cache in the backend pool
// This is called after traffic proxying completes
func recordMetrics(state *ConnectionState) {
	duration := time.Since(state.StartTime)
	log.Printf("connection completed: in=%d out=%d duration=%v", state.BytesIn, state.BytesOut, duration)

	// Update pool connection statistics for load balancing decisions
	// The pool's connCache tracks active connection durations
	state.Pool.connCache.Store(state.Upstream.RemoteAddr().String(), duration)
}

// healthCheckHandler provides liveness/readiness probes for K8s
func healthCheckHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

// watchServiceEndpoints simulates K8s endpoint watch for service discovery
func watchServiceEndpoints(ctx context.Context) {
	// In production, this would use client-go informers
	// Simulating initial registration
	backendHost := os.Getenv("BACKEND_SERVICE_HOST")
	if backendHost == "" {
		backendHost = "backend.default.svc.cluster.local"
	}

	pool := &BackendPool{
		Endpoints: []string{"10.0.0.1:8080", "10.0.0.2:8080"},
		Healthy:   []bool{true, true},
		TLSConfig: &tls.Config{
			InsecureSkipVerify: false,
			MinVersion:         tls.VersionTLS12,
		},
	}
	registry.Register(backendHost, pool)

	// Simulate endpoint churn - services get deregistered on scale-down
	go func() {
		for {
			select {
			case <-ctx.Done():
				return
			case <-time.After(60 * time.Second):
				// Endpoint reconciliation could temporarily remove pools
				registry.mu.Lock()
				delete(registry.backends, backendHost)
				registry.mu.Unlock()

				time.Sleep(100 * time.Millisecond)

				registry.Register(backendHost, pool)
			}
		}
	}()
}

func extractTargetHost(conn net.Conn) string {
	// In a real sidecar proxy, this would parse ORIGINAL_DST from iptables redirect
	// or use the PROXY protocol header
	localAddr := conn.LocalAddr().String()
	host, _, _ := net.SplitHostPort(localAddr)
	if strings.HasPrefix(host, "10.") {
		return os.Getenv("BACKEND_SERVICE_HOST")
	}
	return host
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	watchServiceEndpoints(ctx)

	// Health check endpoint for K8s probes
	go func() {
		mux := http.NewServeMux()
		mux.HandleFunc("/healthz", healthCheckHandler)
		mux.HandleFunc("/readyz", healthCheckHandler)
		http.ListenAndServe(":15021", mux)
	}()

	// Main proxy listener
	listener, err := net.Listen("tcp", ":15001")
	if err != nil {
		log.Fatalf("failed to start proxy listener: %v", err)
	}
	defer listener.Close()

	log.Println("sidecar proxy started on :15001")

	for {
		conn, err := listener.Accept()
		if err != nil {
			log.Printf("accept error: %v", err)
			continue
		}

		targetHost := extractTargetHost(conn)
		go handleConnection(conn, targetHost)
	}
}
